        int max_length = 1;
        for(int i = 1; i < nums.size(); i++){
            if( nums[i] == nums[i-1] ) continue;
            else if( nums[i] == nums[i-1] + 1 ) seq_length++;
            else seq_length = 1;
            max_length = max(max_length, seq_length);
        }
        return max_length;
    }
};

